import json,zipfile,pathlib,re
z=zipfile.ZipFile('/mnt/data/GMRI_Private_Canonical_Evidence_and_Threat_Model_v3_2026-10-27(20261105-203806).zip')
terms={'insurrection':re.compile(r'insurrect',re.I),'threatening physical harm':re.compile(r'(physically (harm|attack)|violent intent|commit violence|incit(e|ement)|terroris)',re.I),'ADA':re.compile(r'ADA|accommodation|discrimination',re.I)}
for term,pat in terms.items():
 print('\n===',term)
 out=[];seen=set()
 for name in z.namelist():
  if not name.startswith('original_exports/') or not name.endswith('.json'):continue
  d=json.loads(z.read(name));cid=d.get('conversationId');
  for m in d['messages']:
   key=(cid,m.get('index'))
   if key in seen:continue
   seen.add(key)
   s=m.get('text','')
   if pat.search(s):out.append((name.split('/')[-1],m['index'],m['role'],re.sub(r'\s+',' ',s)[:220]))
 print('matches',len(out));[print(*t,sep=' | ') for t in out[:35]]
